import { Blok } from '@bloklabs/core';
import { Page } from '@bloklabs/core/tools';
import type { PageConfig, PageIcon, PageInfo } from '@bloklabs/core/tools';

type HostIcon = { type: string; value: string | null; url: string | null };
type HostRecord = { pageId: string; title: string; icon: HostIcon | null; version: number };

const json = { 'content-type': 'application/json' };
// The CAS handle: the version of the record this tab last read.
const versions = new Map<string, number>();
const listeners = new Map<string, Set<() => void>>();
let events: EventSource | null = null;

const notify = (pageId: string): void => listeners.get(pageId)?.forEach((listener) => listener());

const toIcon = (icon: HostIcon | null): PageIcon | undefined => {
  if (icon?.type === 'emoji' && icon.value !== null) {
    return { type: 'emoji', value: icon.value };
  }
  if (icon?.type === 'image' && icon.url !== null) {
    return { type: 'image', url: icon.url };
  }

  return undefined;
};

const toInfo = (record: HostRecord): PageInfo => {
  const icon = toIcon(record.icon);

  return icon === undefined ? { title: record.title } : { title: record.title, icon };
};

const write = async (pageId: string, path: 'title' | 'icon', payload: object): Promise<void> => {
  const response = await fetch(`/api/pages/${encodeURIComponent(pageId)}/${path}`, {
    method: 'PUT',
    headers: json,
    body: JSON.stringify({ ...payload, expectedVersion: versions.get(pageId) ?? 0 }),
  });

  if (!response.ok) {
    // 409 or 403: throw, and Blok asks resolve() again for the host's value.
    throw new Error(`page ${path} save failed: ${response.status}`);
  }
  versions.set(pageId, ((await response.json()) as HostRecord).version);
  notify(pageId);
};

export const pageConfig: PageConfig = {
  href: (pageId) => `/pages/${encodeURIComponent(pageId)}`,
  open: (pageId) => {
    window.location.assign(`/pages/${encodeURIComponent(pageId)}`);
  },
  create: async ({ pageId }) => {
    const response = await fetch('/api/pages', { method: 'POST', headers: json, body: JSON.stringify({ pageId }) });

    if (!response.ok) {
      throw new Error(`page create failed: ${response.status}`);
    }
    const record = (await response.json()) as HostRecord;

    versions.set(record.pageId, record.version);

    return { pageId: record.pageId };
  },
  resolve: async (pageId) => {
    const response = await fetch(`/api/pages/${encodeURIComponent(pageId)}`, { cache: 'no-store' });

    // Before the 404 check: a followed login redirect can end in a 404.
    if (response.redirected || response.status === 401 || response.status === 403) {
      return undefined;
    }
    if (response.status === 404) {
      return null;
    }
    if (!response.ok) {
      return undefined;
    }
    const body = (await response.json()) as HostRecord | { pageId: string; access: 'none' };

    if ('access' in body) {
      return { access: 'none' };
    }
    versions.set(pageId, body.version);

    return toInfo(body);
  },
  subscribe: (pageId, onChange) => {
    const set = listeners.get(pageId) ?? new Set<() => void>();

    set.add(onChange);
    listeners.set(pageId, set);
    if (events === null) {
      events = new EventSource('/api/pages/events');
      events.onmessage = (event: MessageEvent<string>) => notify((JSON.parse(event.data) as { pageId: string }).pageId);
      // The server dropped events for this tab: re-resolve every page.
      events.addEventListener('resync', () => listeners.forEach((_, id) => notify(id)));
    }

    return () => {
      set.delete(onChange);
    };
  },
  rename: (pageId, title) => write(pageId, 'title', { title }),
  setIcon: (pageId, icon) => write(pageId, 'icon', { icon }),
};

// The page body: its own Blok document, named by the page id.
export const openPageBody = (holder: HTMLElement, pageId: string): Blok =>
  new Blok({
    holder,
    server: '/api/blok',
    collaboration: { doc: pageId },
    tools: { page: { class: Page, config: { ...pageConfig } } },
  });

import type { Title, TitleChange } from '@bloklabs/core';

type PageRecord = {
  pageId: string;
  title: string;
  icon?: string;
  version: number;
};

type PageHost = {
  loadPage(pageId: string): Promise<PageRecord>;
  saveTitle(pageId: string, title: string, expectedVersion: number): Promise<PageRecord>;
  subscribe(pageId: string, notify: () => void): () => void;
  notify(pageId: string): void;
};

async function wireTitle(
  pageId: string,
  host: PageHost,
  editor: { title: Title },
  paint: (title: string) => void,
  showError: () => void
): Promise<{ change: (title: string, change: TitleChange) => void; stop: () => void }> {
  let accepted = await host.loadPage(pageId);
  let displayed = accepted.title;
  let latestWrite = 0;
  let latestRead = 0;
  let pending = 0;
  let stopped = false;
  let queue: Promise<void> = Promise.resolve();

  editor.title.set(accepted.title, { record: false });
  paint(accepted.title);

  function showAccepted(): void {
    if (stopped) return;
    displayed = accepted.title;
    editor.title.set(displayed, { record: false });
    paint(displayed);
    host.notify(pageId);
  }

  function changeTitle(next: string): void {
    if (stopped || next === displayed) return;
    const ticket = ++latestWrite;

    displayed = next;
    paint(next);
    host.notify(pageId);
    pending += 1;
    queue = queue.then(async () => {
      try {
        if (stopped) return;
        const saved = await host.saveTitle(pageId, next, accepted.version);

        if (saved.version > accepted.version) accepted = saved;
        if (ticket === latestWrite) showAccepted();
      } catch {
        try {
          const current = await host.loadPage(pageId);

          if (current.version > accepted.version) accepted = current;
          // A rejected earlier request must not replace a later local edit.
          if (ticket === latestWrite && !stopped) {
            showAccepted();
            showError();
          }
        } catch {
          if (!stopped) {
            stop();
            paint('');
            host.notify(pageId);
            showError();
          }
        }
      } finally {
        pending -= 1;
      }
    });
  }

  function refreshFromHost(): void {
    const order = ++latestRead;

    void host.loadPage(pageId).then((record) => {
      if (stopped || order !== latestRead) return;
      const newer = record.version > accepted.version;
      if (newer) accepted = record;
      if (pending === 0 && (newer || editor.title.get() !== accepted.title || displayed !== accepted.title)) {
        showAccepted();
      }
    }).catch(() => {
      if (stopped || order !== latestRead) return;
      stop();
      paint('');
      host.notify(pageId);
    });
  }

  const unsubscribe = host.subscribe(pageId, refreshFromHost);

  function stop(): void {
    stopped = true;
    latestRead += 1;
    unsubscribe();
  }

  return {
    // Call it from pageTitle.onChange.
    change: (title, { source, record }) => {
      // Our own record:false write: the value came from the host.
      if (source === 'api' && record === false) return;
      if (source === 'remote') {
        refreshFromHost();
        return;
      }
      changeTitle(title);
    },
    stop,
  };
}

